"""Install bounded audited editorial recovery; never starts a production run."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile
from pathlib import Path
MANIFEST={'runner.py': {'old': '4594a6e2026795448ef615f0e37d49622d95cc39af2ecded938380f301dc6c0d', 'new': '6834f24acd9bd740974da0781bd2e8f05191d1ce925662bc993f9f73268c9c7c', 'body': ''}, 'recovery.py': {'old': '1d2802e56eea040323776187cb74858a4351bf6220c678bb1ff4d4849ff61ded', 'new': '00ecbd418cb4751c85a91bc414efe77260b495719f1ee2d4d72fb206756bfc7e', 'body': ''}, 'editor-prompt.md': {'old': '551b9a02c6bea880eb48512c185b712bf94f9601696d564fe1b5b47ca954f7db', 'new': 'c67f656ecd6c5638ef498776821f24a6d3110d162242e1056a893016c90db08f', 'body': ''}, 'test_editor_handoff.py': {'old': None, 'new': '67f93d18e95e0c9d96ac98af07f5dcdba59ae29b421db4ce3b01fd3b3d0ffee3', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.handoff-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo/automation/server');store=Path('/var/lib/fh6');prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        if n.endswith('.py'):compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('editor-handoff-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.write_bytes(before);saved.chmod(0o600)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_editor_handoff','test_recovery','test_install_recovery'],cwd=root,check=True,timeout=90)
            subprocess.run(['/usr/bin/python3','automation/test_refresh_guard.py'],cwd=root.parents[1],check=True,timeout=90)
            subprocess.run(['/usr/bin/python3','automation/test_portable_report.py'],cwd=root.parents[1],check=True,timeout=240)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            raise
        print('EDITOR_HANDOFF_RECOVERY_INSTALLED bounded evidence-aware completion, validated rollover, rollback; no production refresh started',flush=True)
        print('BACKUP='+str(backup),flush=True)
if __name__=='__main__':main()
